// Out-of-band (OOB) token minting + correlation helper.
// Every blind-class payload generated by attack modules MUST embed one of
// these tokens so the oob-collector + reaper can confirm exploitation.

const SUPA_URL = Deno.env.get("SUPABASE_URL")!;

export interface OobToken {
  token: string;
  httpUrl: string;       // http(s) callback for SSRF / XXE / log4shell
  dnsHost: string;       // host-form for JNDI / DNS pingbacks
  ctx: string;
}

export function mintOobToken(opts: { runId?: string | null; targetId?: string | null; vulnClass: string; nonce?: string }): OobToken {
  const n = opts.nonce || Math.random().toString(36).slice(2, 10);
  const r = (opts.runId || opts.targetId || "anon").toString().replace(/-/g, "").slice(0, 12);
  const token = `${r}-${opts.vulnClass.slice(0, 6)}-${n}`;
  const httpUrl = `${SUPA_URL}/functions/v1/oob-collector?token=${token}&ctx=${encodeURIComponent(opts.vulnClass)}`;
  // synthetic DNS-style label (collector reads token from query when host is reused)
  let host = "oob.cyberscope.local";
  try { host = new URL(SUPA_URL).host; } catch { /* keep default */ }
  const dnsHost = `${token}.${host}`;
  return { token, httpUrl, dnsHost, ctx: opts.vulnClass };
}

/** Insert a pending OOB seed so the reaper can correlate. Best-effort. */
export async function seedOob(
  db: any,
  tok: OobToken,
  opts: { targetId: string; runId?: string | null; injectionPoint?: string; payload?: string }
): Promise<void> {
  try {
    await db.from("oob_callbacks").insert({
      token: tok.token,
      target_id: opts.targetId,
      callback_type: tok.ctx === "dns" ? "dns" : "http",
      payload_context: opts.injectionPoint || tok.ctx,
      vuln_class: tok.ctx,
    });
  } catch { /* ignore */ }
}
